// =========================================================================
// REGLAS OPERATIVAS DEL PROTOTIPO - DataCenter Andino S.A.C.
// IMPORTANTE: Para evitar series triplicadas en InfluxDB y Grafana, los tags
// contienen únicamente identificadores estáticos (node_id y location).
// Los estados (NORMAL, ADVERTENCIA, CRITICO) se almacenan como fields.
//
// Salidas del nodo:
//   1 -> lectura válida hacia la medición 'ambiente_sala'
//   2 -> alerta de TEMPERATURA_CRITICA (InfluxDB 'eventos_alerta' + tópico MQTT de alertas)
//   3 -> evento MEDICION_INVALIDA (solo InfluxDB 'eventos_alerta'; no es una alerta crítica)
//
// Todos los tiempos se miden con el reloj de Node-RED. El reloj del ESP32 simulado
// no se usa para medir, porque se atrasa cuando la simulación corre por debajo del 100 %.
// =========================================================================

const rxTimeMs = Date.now();
const p = msg.payload;

if (!p || typeof p !== 'object') {
    node.warn("Mensaje descartado: formato JSON inválido");
    return [null, null, null];
}

const temp = Number(p.temperature_c);
const hum  = Number(p.humidity_pct);
const light = Number(p.light_pct);
const lightLux = Number(p.light_lux || 0);
const ldrRaw = Number(p.ldr_raw || 0);
const seqId = Number(p.seq_id || 0);

const tags = {
    node_id: p.node_id || "esp32-sala-01",
    location: p.location || "Sala_Servidores_Principal"
};

// 1. Validar errores de sensor (NaN, nulos o fuera de rango físico)
if (p.sensor_error === true || p.temperature_c === null || isNaN(temp) || isNaN(light) || temp < -10 || temp > 85 || light < 0 || light > 100) {
    node.warn(`Medición inválida descartada en seq_id=${seqId}`);
    const invalidEvent = {
        measurement: "eventos_alerta",
        payload: [
            {
                tipo_evento: "MEDICION_INVALIDA",
                mensaje: `Lectura inválida (NaN o fuera de rango) filtrada por Node-RED en seq_id=${seqId}`,
                seq_id: seqId
            },
            Object.assign({ severidad: "ERROR_SENSOR" }, tags)
        ]
    };
    return [null, null, invalidEvent];
}

// 2. Clasificación de Temperatura (Regla 4)
let estadoTemp = "NORMAL";
let codigoEstadoTemp = 0; // 0=NORMAL (<28°C), 1=ADVERTENCIA (28-29.9°C), 2=CRITICO (>=30°C)
if (temp >= 30.0) {
    estadoTemp = "CRITICO";
    codigoEstadoTemp = 2;
} else if (temp >= 28.0) {
    estadoTemp = "ADVERTENCIA";
    codigoEstadoTemp = 1;
}

// 3. Clasificación de Iluminación (Porcentaje calibrado del LDR)
let estadoLuz = "APAGADO";
let codigoEstadoLuz = 0; // 0=APAGADO (<20%), 1=ILUMINACION_PARCIAL (20-59%), 2=ENCENDIDO (>=60%)
if (light >= 60.0) {
    estadoLuz = "ENCENDIDO";
    codigoEstadoLuz = 2;
} else if (light >= 20.0) {
    estadoLuz = "ILUMINACION_PARCIAL";
    codigoEstadoLuz = 1;
}

// 4. Intervalo real entre lecturas consecutivas (ms), medido al recibirlas en Node-RED.
// Se omite en la primera lectura y tras un silencio de más de 60 s (corte de publicaciones).
const lastRx = context.get("lastRxMs");
const lastNonCriticalRx = context.get("lastNonCriticalRxMs");
const wasCritical = context.get("wasCritical") === true;
let intervaloMs = null;
if (typeof lastRx === "number" && rxTimeMs - lastRx <= 60000) {
    intervaloMs = rxTimeMs - lastRx;
}

// 5. Estructura para InfluxDB (Salida 1: Serie Temporal Principal 'ambiente_sala')
// NOTA CRÍTICA: Tags estáticos (node_id, location) -> 1 sola serie continua en Grafana.
const fields = {
    temperature_c: Number(temp.toFixed(2)),
    humidity_pct: Number(hum.toFixed(2)),
    light_pct: Number(light.toFixed(2)),
    light_lux: Number(lightLux.toFixed(1)),
    ldr_raw: ldrRaw,
    estado_temp_str: estadoTemp,
    estado_temp_code: codigoEstadoTemp,
    estado_luz_str: estadoLuz,
    estado_luz_code: codigoEstadoLuz,
    seq_id: seqId
};
if (intervaloMs !== null) {
    fields.intervalo_ms = intervaloMs;
}
const msgInflux = {
    measurement: "ambiente_sala",
    payload: [fields, tags]
};

// 6. Si está en condición CRÍTICA (>= 30 °C), generar evento de alerta inmediata (Salida 2)
// tiempo_deteccion_ms se registra solo en la primera lectura crítica de cada episodio:
// es el tiempo transcurrido desde la última lectura NO crítica recibida hasta que se genera
// la alerta. La sala cruzó el umbral en algún momento de ese intervalo, por lo que es la
// cota superior del tiempo real de detección (aprox. un periodo de muestreo).
let msgAlerta = null;
if (estadoTemp === "CRITICO") {
    const alertFields = {
        tipo_evento: "TEMPERATURA_CRITICA",
        temperature_c: Number(temp.toFixed(2)),
        light_pct: Number(light.toFixed(2)),
        umbral_superado: 30.0,
        mensaje: `ALERTA CRÍTICA: Temperatura alcanzó ${temp.toFixed(2)} °C (>= 30.0 °C). Revisar climatización.`,
        seq_id: seqId
    };
    if (!wasCritical && typeof lastNonCriticalRx === "number" && rxTimeMs - lastNonCriticalRx <= 60000) {
        alertFields.tiempo_deteccion_ms = Date.now() - lastNonCriticalRx;
    }
    msgAlerta = {
        measurement: "eventos_alerta",
        topic: "datacenter_andino/sala_servidores/alertas",
        payload: [
            alertFields,
            Object.assign({ severidad: "CRITICO" }, tags)
        ]
    };
}

context.set("lastRxMs", rxTimeMs);
context.set("wasCritical", estadoTemp === "CRITICO");
if (estadoTemp !== "CRITICO") {
    context.set("lastNonCriticalRxMs", rxTimeMs);
}

return [msgInflux, msgAlerta, null];

// Latencia de ida y vuelta al broker, medida con el reloj de Node-RED.
const enviado = Number(msg.payload && msg.payload.enviado_ms);
const latencia = Date.now() - enviado;
if (!enviado || latencia < 0 || latencia > 30000) {
    return null; // sonda ajena o inválida
}
node.status({ fill: "green", shape: "dot", text: latencia + " ms" });
return {
    measurement: "diagnostico_enlace",
    payload: [
        { latencia_mqtt_ms: latencia },
        { origen: "nodered" }
    ]
};
